import { test, expect } from '@playwright/test';

test.describe('Active Sessions Management', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/user-profile');
  });

  test('should display all active sessions and allow user to log out of a specific one', async ({ page }) => {
    // Verify active sessions list is visible
    const sessionsList = page.getByRole('region', { name: /active sessions/i });
    await expect(sessionsList).toBeVisible();

    // Verify session details are displayed
    const sessionName = page.getByText('Session 1');
    await expect(sessionName).toBeVisible();

    const sessionStatus = page.getByText('Active');
    await expect(sessionStatus).toBeVisible();

    // Verify logout button is present
    const logoutButton = page.getByRole('button', { name: /logout/i });
    await expect(logoutButton).toBeVisible();

    // Verify logout button is disabled for all sessions
    await expect(logoutButton).not.toBeDisabled();

    // Click logout button for Session 1
    await logoutButton.click();

    // Verify logout confirmation modal appears
    const confirmModal = page.getByRole('dialog', { name: /confirm logout/i });
    await expect(confirmModal).toBeVisible();

